import React, { useState, useEffect } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, LineElement, PointElement,
  LinearScale, CategoryScale, Filler, Tooltip, Legend
} from 'chart.js';
import { getGraphConfidence, getGraphTimeline } from '../services/api';
import { useApp } from '../context/AppContext';

ChartJS.register(
  LineElement, PointElement,
  LinearScale, CategoryScale,
  Filler, Tooltip, Legend
);

const CLASS_COLORS = {
  Normal:       '#22c55e',
  Phone:        '#60a5fa',
  Medical_Mask: '#34d399',
  Fire:         '#fb923c',
  Smoke:        '#94a3b8',
  Gun:          '#f87171',
  Knife:        '#facc15',
  Falling:      '#a78bfa',
  Violence:     '#f43f5e',
  Theft_Mask:   '#fbbf24'
};

const gridColor = '#1e2d47';
const tickStyle = { color: '#64748b', font: { size: 9 } };

export default function ChartsRow() {
  const { detectionSummary } = useApp();

  const [confidence, setConfidence] = useState({});
  const [timeline,   setTimeline]   = useState({ labels: [], counts: [] });

  const loadData = async () => {
    try {
      const [confRes, timeRes] = await Promise.all([
        getGraphConfidence(),
        getGraphTimeline()
      ]);
      setConfidence(confRes.data.classes || {});
      setTimeline({
        labels: timeRes.data.labels || [],
        counts: timeRes.data.counts || []
      });
    } catch (err) {
      console.warn('[ChartsRow] Load failed:', err);
    }
  };

  // Load on mount + refresh every 5s
  useEffect(() => {
    loadData();
    const id = setInterval(loadData, 3000);
    return () => clearInterval(id);
  }, []);

  // ── Confidence chart — ALL classes ───────────────────────────
  // Build from detectionSummary (all classes) +
  // real confidence scores from API
  const allClasses = Object.keys(CLASS_COLORS);

  // Labels = last N points
  const maxLen = Math.max(
    ...Object.values(confidence).map(v => v.length),
    8
  );
  const confLabels = Array.from(
    { length: maxLen },
    (_, i) => `${i + 1}`
  );

  // Build dataset for every class
  const confDatasets = allClasses.map(cls => {
    const points  = confidence[cls] || [];
    const count   = detectionSummary[cls] || 0;
    const color   = CLASS_COLORS[cls];

    // If we have real confidence points use them
    // Otherwise show flat line at count-based level
    let data;
    if (points.length > 0) {
      // Pad left with nulls to align right
      const padded = Array(maxLen - points.length).fill(null);
      data = [...padded, ...points.map(p => p.confidence)];
    } else if (count > 0) {
      // Class detected but no conf data — show at 0.5
      data = Array(maxLen).fill(0.5);
    } else {
      // No detections — flat at 0
      data = Array(maxLen).fill(0);
    }

    return {
      label:       cls,
      data,
      borderColor: color,
      borderWidth: cls === 'Normal' ? 2 : 1.5,
      pointRadius: points.length > 0 ? 3 : 0,
      fill:        false,
      tension:     0.4,
      spanGaps:    true
    };
  });

  const confChartData = {
    labels:   confLabels,
    datasets: confDatasets
  };

  // ── Timeline chart ───────────────────────────────────────────
  const timelineChartData = {
    labels:   timeline.labels,
    datasets: [{
      label:           'Detections',
      data:            timeline.counts,
      borderColor:     '#3b82f6',
      borderWidth:     2,
      fill:            true,
      backgroundColor: 'rgba(59,130,246,.08)',
      pointRadius:     0,
      tension:         0.4
    }]
  };

  // ── Options ──────────────────────────────────────────────────
  const confOpts = {
    animation:  false,
    responsive: true,
    plugins: {
      legend: {
        display:  true,
        position: 'bottom',
        labels: {
          color:    '#64748b',
          font:     { size: 8 },
          boxWidth: 8,
          padding:  6,
          // Only show classes that have detections
          filter: (item) => {
            const cls   = item.text;
            const count = detectionSummary[cls] || 0;
            const pts   = confidence[cls]       || [];
            return count > 0 || pts.length > 0;
          }
        }
      },
      tooltip: {
        callbacks: {
          label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.y?.toFixed(2) ?? 'N/A'}`
        }
      }
    },
    scales: {
      x: {
        ticks: { color: '#64748b', font: { size: 8 }, maxTicksLimit: 6 },
        grid:  { color: gridColor }
      },
      y: {
        min:   0,
        max:   1,
        ticks: { color: '#64748b', font: { size: 9 }, stepSize: .25 },
        grid:  { color: gridColor }
      }
    }
  };

  const timeOpts = {
  animation:  false,
  responsive: true,
  plugins:    { legend: { display: false } },
  scales: {
    x: {
      ticks: { color: '#64748b', font: { size: 8 }, maxTicksLimit: 7 },
      grid:  { color: gridColor }
    },
    y: {
      min:   0,       // ← No negative values!
      ticks: { color: '#64748b', font: { size: 9 } },
      grid:  { color: gridColor }
    }
  }
};

  return (
    <div style={{
      display:             'grid',
      gridTemplateColumns: '1fr 1fr',
      gap:                 8,
      marginBottom:        10
    }}>

      {/* Confidence Score Graph */}
      <div style={{
        background:   '#151d2e',
        border:       '1px solid #1e2d47',
        borderRadius: 8,
        padding:      10
      }}>
        <div style={{
          display:        'flex',
          justifyContent: 'space-between',
          alignItems:     'center',
          marginBottom:   6
        }}>
          <span style={{
            fontSize:      11,
            fontWeight:    700,
            color:         '#94a3b8',
            textTransform: 'uppercase',
            letterSpacing: '.5px'
          }}>
            Confidence Score Graph
          </span>
          <div style={{ display: 'flex', gap: 4 }}>
            <select style={{
              background:   '#1a2340',
              border:       '1px solid #253550',
              color:        '#94a3b8',
              fontSize:     10,
              padding:      '2px 5px',
              borderRadius: 4
            }}>
              <option>All Classes</option>
            </select>
            <select style={{
              background:   '#1a2340',
              border:       '1px solid #253550',
              color:        '#94a3b8',
              fontSize:     10,
              padding:      '2px 5px',
              borderRadius: 4
            }}>
              <option>Today</option>
            </select>
          </div>
        </div>

        <Line data={confChartData} options={confOpts} />
      </div>

      {/* Detections Over Time */}
      <div style={{
        background:   '#151d2e',
        border:       '1px solid #1e2d47',
        borderRadius: 8,
        padding:      10
      }}>
        <div style={{
          display:        'flex',
          justifyContent: 'space-between',
          alignItems:     'center',
          marginBottom:   6
        }}>
          <span style={{
            fontSize:      11,
            fontWeight:    700,
            color:         '#94a3b8',
            textTransform: 'uppercase',
            letterSpacing: '.5px'
          }}>
            Detections Over Time
          </span>
          <div style={{ display: 'flex', gap: 4 }}>
            <select style={{
              background:   '#1a2340',
              border:       '1px solid #253550',
              color:        '#94a3b8',
              fontSize:     10,
              padding:      '2px 5px',
              borderRadius: 4
            }}>
              <option>All Classes</option>
            </select>
            <select style={{
              background:   '#1a2340',
              border:       '1px solid #253550',
              color:        '#94a3b8',
              fontSize:     10,
              padding:      '2px 5px',
              borderRadius: 4
            }}>
              <option>Today</option>
            </select>
          </div>
        </div>

        <Line data={timelineChartData} options={timeOpts} />
      </div>

    </div>
  );
}
